def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = data[2]

    chars = [chr(ord('a') + i) for i in range(26)]
    start = (0,) * (N + 1)

    cache = {}

    def next_state(state, ch):
        key = (state, ch)
        if key in cache:
            return cache[key]

        old = list(state)
        new = [0] * (N + 1)
        new[0] = 0

        for i in range(1, N + 1):
            best = old[i]
            if new[i - 1] > best:
                best = new[i - 1]

            if S[i - 1] == ch:
                cand = old[i - 1] + 1
                if cand > best:
                    best = cand

            new[i] = best

        res = tuple(new)
        cache[key] = res
        return res

    dp = {start: 1}

    for _ in range(M):
        ndp = {}
        for state, cnt in dp.items():
            for ch in chars:
                ns = next_state(state, ch)
                ndp[ns] = (ndp.get(ns, 0) + cnt) % MOD
        dp = ndp

    ans = [0] * (N + 1)

    for state, cnt in dp.items():
        k = state[N]
        ans[k] = (ans[k] + cnt) % MOD

    print(" ".join(map(str, ans)))

