    res = []
    d = 2
    while d * d <= x:
        if x % d == 0:
            e = 0
            while x % d == 0:
                x //= d
                e += 1
            res.append((d, e))
        d += 1 if d == 2 else 2
    if x > 1:
        res.append((x, 1))
    return res


def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    N = int(data[0])
    A = list(map(int, data[1:1 + N - 1]))

    primes_set = set()
    for a in A:
        for p, _ in factorize(a):
            primes_set.add(p)

    exps = {p: [0] * (N - 1) for p in primes_set}
    for i, a in enumerate(A):
        for p, e in factorize(a):
            exps[p][i] = e

    ans = 1

    for p in primes_set:
        e_list = exps[p]
        E = sum(e_list)
        if E == 0:
            continue

        max_x = 2 * E + 5
        p_mod = p % MOD

        powp = [1] * (max_x + 1)
